/**
 * Cross-platform process spawning utilities
 */

import { spawn } from 'cross-spawn';
import type { SpawnOptions } from 'node:child_process';
import { TimeoutError, ExecutionError } from './errors';

/**
 * Spawn result
 */
export interface SpawnResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  duration: number;
}

/**
 * Spawn options with callbacks
 */
export interface SpawnWithCallbacksOptions {
  args?: string[];
  cwd?: string;
  env?: Record<string, string>;
  timeout?: number;
  onStdout?: (chunk: string) => void;
  onStderr?: (chunk: string) => void;
  verbose?: boolean;
}

/**
 * Spawn a process and collect output
 */
export async function spawnProcess(command: string, options: SpawnWithCallbacksOptions = {}): Promise<SpawnResult> {
  const { args = [], cwd, env, timeout, onStdout, onStderr, verbose } = options;

  const startTime = Date.now();
  let stdout = '';
  let stderr = '';
  let timedOut = false;
  let timeoutHandle: NodeJS.Timeout | undefined;

  const spawnOptions: SpawnOptions = {
    cwd: cwd || process.cwd(),
    env: env ? { ...process.env, ...env } : process.env,
    stdio: ['ignore', 'pipe', 'pipe'],
  };

  // Verbose logging for debugging
  if (verbose) {
    process.stderr.write('[agent-cli-sdk:spawn] ========== SPAWNING PROCESS ==========\n');
    process.stderr.write(`[agent-cli-sdk:spawn] Command: ${command}\n`);
    process.stderr.write(`[agent-cli-sdk:spawn] Arguments: ${JSON.stringify(args, null, 2)}\n`);
    process.stderr.write(`[agent-cli-sdk:spawn] Working Directory (cwd): ${spawnOptions.cwd}\n`);
    process.stderr.write(`[agent-cli-sdk:spawn] Timeout: ${timeout ? `${timeout}ms` : 'none'}\n`);

    // Log environment variables (redact sensitive keys)
    if (env) {
      const redactedEnv = { ...env };
      if (redactedEnv['ANTHROPIC_API_KEY']) {
        redactedEnv['ANTHROPIC_API_KEY'] = '***REDACTED***';
      }
      if (redactedEnv['CLAUDE_CODE_OAUTH_TOKEN']) {
        redactedEnv['CLAUDE_CODE_OAUTH_TOKEN'] = '***REDACTED***';
      }
      process.stderr.write(`[agent-cli-sdk:spawn] Environment Variables (custom): ${JSON.stringify(redactedEnv)}\n`);
    }
    process.stderr.write('[agent-cli-sdk:spawn] ==========================================\n');
  }

  return new Promise((resolve, reject) => {
    const child = spawn(command, args, spawnOptions);

    if (!child.stdout || !child.stderr) {
      reject(new ExecutionError('Failed to spawn process: no stdio streams'));
      return;
    }

    // Set up timeout
    if (timeout) {
      timeoutHandle = setTimeout(() => {
        timedOut = true;
        child.kill('SIGTERM');

        // Force kill after 2 seconds if still alive
        setTimeout(() => {
          if (!child.killed) {
            child.kill('SIGKILL');
          }
        }, 2000);
      }, timeout);
    }

    // Collect stdout
    child.stdout.on('data', (chunk: Buffer) => {
      const str = chunk.toString();
      stdout += str;
      onStdout?.(str);
    });

    // Collect stderr
    child.stderr.on('data', (chunk: Buffer) => {
      const str = chunk.toString();
      stderr += str;
      onStderr?.(str);
    });

    // Handle process exit
    child.on('close', (code: number | null) => {
      if (timeoutHandle) {
        clearTimeout(timeoutHandle);
      }

      const duration = Date.now() - startTime;

      if (timedOut) {
        reject(new TimeoutError(timeout!, `Process exceeded timeout of ${timeout}ms`));
        return;
      }

      resolve({
        stdout,
        stderr,
        exitCode: code ?? 1,
        duration,
      });
    });

    // Handle spawn errors
    child.on('error', (err: Error) => {
      if (timeoutHandle) {
        clearTimeout(timeoutHandle);
      }

      reject(new ExecutionError(`Failed to spawn process: ${err.message}`, undefined, stderr));
    });
  });
}

